    63  /** Convert a STRUCT to one or more VPs
    64   *
    65   */
    66  ssize_t fr_struct_from_network(TALLOC_CTX *ctx, fr_dcursor_t *cursor,
    67                                 fr_dict_attr_t const *parent, uint8_t const *data, size_t data_len,
    68                                 bool nested, void *decode_ctx,
    69                                 fr_decode_value_t decode_value, fr_decode_value_t decode_tlv)
    70  {
    71          unsigned int            child_num;
    72          uint8_t const           *p = data, *end = data + data_len;
    73          fr_dict_attr_t const    *child;
    74          fr_pair_list_t          head;
    75          fr_dcursor_t            child_cursor;
    76          fr_pair_t               *vp, *key_vp, *struct_vp = NULL;
    77          unsigned int            offset = 0;
    78          TALLOC_CTX              *child_ctx;
    79
    80          if (data_len < 1) return -1; /* at least one byte of data */
    81
    82          FR_PROTO_HEX_DUMP(data, data_len, "fr_struct_from_network");
    83
    84          /*
    85           *      Start a child list.
    86           */
    87          if (!nested) {
    88                  fr_pair_list_init(&head);
    89                  fr_dcursor_init(&child_cursor, &head);
    90                  child_ctx = ctx;
    91          } else {
    92                  fr_assert(parent->type == FR_TYPE_STRUCT);
    93
    94                  struct_vp = fr_pair_afrom_da(ctx, parent);
    95                  if (!struct_vp) return -1;
    96
    97                  fr_pair_list_init(&head); /* still used elsewhere */
    98                  fr_dcursor_init(&child_cursor, &struct_vp->vp_group);
    99                  child_ctx = struct_vp;
   100          }
   101          child_num = 1;
   102          key_vp = NULL;
   103
   104          /*
   105           *      Decode structs with length prefixes.
   106           */
   107          if (da_is_length_field(parent)) {
   108                  size_t struct_len;
   109
   110                  struct_len = (p[0] << 8) | p[1];
   111                  if ((struct_len + 2) > data_len) {
   112                          FR_PROTO_TRACE("too much data?");
   113                          goto unknown;
   114                  }
   115
   116                  data_len = struct_len + 2;
   117                  end = data + data_len;
   118                  p += 2;
   119          }
   120
   121          while (p < end) {
   122                  size_t child_length;
   123
   124                  /*
   125                   *      Go to the next child.  If it doesn't exist, we're done.
   126                   */
   127                  child = fr_dict_attr_child_by_num(parent, child_num);
   128                  if (!child) break;
   129
   130                  FR_PROTO_HEX_DUMP(p, (end - p), "fr_struct_from_network - child %s (%d)", child->name, child->attr);
   131
   132                  /*
   133                   *      Check for bit fields.
   134                   */
   135                  if (da_is_bit_field(child)) {
   136                          uint8_t array[8];
   137                          unsigned int num_bits;
   138                          uint64_t value;
   139
   140                          num_bits = offset + child->flags.length;
   141                          if ((end - p) < fr_bytes_from_bits(num_bits)) {
   142                                  FR_PROTO_TRACE("not enough data for bit decoder?");
   143                                  goto unknown;
   144                          }
   145
   146                          memset(array, 0, sizeof(array));
   147                          memcpy(&array[0], p, fr_bytes_from_bits(num_bits));
   148
   149                          if (offset > 0) array[0] &= (1 << (8 - offset)) - 1; /* mask off bits we don't care about */
   150
   151                          memcpy(&value, &array[0], sizeof(value));
   152                          value = htonll(value);
   153                          value >>= (8 - offset); /* move it to the lower bits */
   154                          value >>= (56 - child->flags.length);
   155
   156                          vp = fr_pair_afrom_da(child_ctx, child);
   157                          if (!vp) {
   158                                  FR_PROTO_TRACE("fr_struct_from_network - failed allocating child VP");
   159                                  goto unknown;
   160                          }
   161
   162                          switch (child->type) {
   163                                  case FR_TYPE_BOOL:
   164                                          vp->vp_bool = value;
   165                                          break;
   166
   167                                  case FR_TYPE_UINT8:
   168                                          vp->vp_uint8 = value;
   169                                          break;
   170
   171                                  case FR_TYPE_UINT16:
   172                                          vp->vp_uint16 = value;
   173                                          break;
   174
   175                                  case FR_TYPE_UINT32:
   176                                          vp->vp_uint32 = value;
   177                                          break;
   178
   179                                  case FR_TYPE_UINT64:
   180                                          vp->vp_uint64 = value;
   181                                          break;
   182
   183                                  default:
   184                                          FR_PROTO_TRACE("Can't decode unknown type?");
   185                                          goto unknown;
   186                          }
   187
   188                          vp->type = VT_DATA;
   189                          vp->vp_tainted = true;
   190                          fr_dcursor_append(&child_cursor, vp);
   191                          p += (num_bits >> 3); /* go to the LAST bit, not the byte AFTER the last bit */
   192                          offset = num_bits & 0x07;
   193                          child_num++;
   194                          continue;
   195                  }
   196                  offset = 0;     /* reset for non-bit-field attributes */
   197
   198                  /*
   199                   *      Decode child TLVs, according to the parent attribute.
   200                   */
   201                  if (child->type == FR_TYPE_TLV) {
   202                          ssize_t slen;
   203
   204                          fr_assert(!key_vp);
   205
   206                          if (!decode_tlv) {
   207                                  fr_strerror_const("Decoding TLVs requires a decode_tlv() function to be passed");
   208                                  return -(p - data);
   209                          }
   210
   211                          /*
   212                           *      Decode EVERYTHING as a TLV.
   213                           */
   214                          while (p < end) {
   215                                  slen = decode_tlv(child_ctx, &child_cursor, fr_dict_by_da(child), child, p, end - p, decode_ctx);
   216                                  if (slen < 0) {
   217                                          FR_PROTO_TRACE("failed decoding TLV?");
   218                                          goto unknown;
   219                                  }
   220                                  p += slen;
   221                          }
   222
   223                          goto done;
   224                  }
   225
   226                  child_length = child->flags.length;
   227
   228                  /*
   229                   *      If this field overflows the input, then *all*
   230                   *      of the input is suspect.
   231                   */
   232                  if ((p + child_length) > end) {
   233                          FR_PROTO_TRACE("fr_struct_from_network - child length %zd overflows buffer", child_length);
   234                          goto unknown;
   235                  }
   236
   237                  if (!child_length) child_length = (end - p);
   238
   239                  /*
   240                   *      Magic values get the callback called.
   241                   *
   242                   *      Note that if this is an *array* of DNS labels,
   243                   *      the callback should deal with this.
   244                   */
   245                  if (decode_value) {
   246                          ssize_t slen;
   247
   248                          slen = decode_value(child_ctx, &child_cursor, fr_dict_by_da(child), child, p, child_length, decode_ctx);
   249                          if (slen < 0) {
   250                                  FR_PROTO_TRACE("Failed decoding value");
   251                                  return slen - (p - data);
   252                          }
   253
   254                          p += slen;      /* not always the same as child->flags.length */
   255                          child_num++;    /* go to the next child */
   256                          if (fr_dict_attr_is_key_field(child)) key_vp = fr_dcursor_tail(&child_cursor);
   257                          continue;
   258                  }
   259
   260                  /*
   261                   *      We only allow a limited number of data types
   262                   *      inside of a struct.
   263                   */
   264                  switch (child->type) {
   265                  default:
   266                          FR_PROTO_TRACE("fr_struct_from_network - unknown child type");
   267                          goto unknown;
   268
   269                  case FR_TYPE_LEAF:
   270                          break;
   271                  }
   272
   273                  vp = fr_pair_afrom_da(child_ctx, child);
   274                  if (!vp) {
   275                          FR_PROTO_TRACE("fr_struct_from_network - failed allocating child VP");
   276                          goto unknown;
   277                  }
   278
   279                  /*
   280                   *      No protocol-specific data types here (yet).
   281                   *
   282                   *      If we can't decode this field, then the entire
   283                   *      structure is treated as a raw blob.
   284                   */
   285                  if (fr_value_box_from_network(vp, &vp->data, vp->da->type, vp->da,
   286                                                &FR_DBUFF_TMP(p, child_length), child_length, true) < 0) {
   287                          FR_PROTO_TRACE("fr_struct_from_network - failed decoding child VP");
   288                          talloc_free(vp);
   289                  unknown:
   290                          if (nested) {
   291                                  TALLOC_FREE(struct_vp);
   292                          } else {
   293                                  fr_pair_list_free(&head);
   294                          }
   295
   296                          vp = fr_raw_from_network(ctx, parent, data, data_len);
   297                          if (!vp) return -1;
   298
   299                          /*
   300                           *      And append this one VP to the output cursor.
   301                           */
   302                          fr_dcursor_append(cursor, vp);
   303                          return data_len;
   304                  }
   305
   306                  vp->type = VT_DATA;
   307                  vp->vp_tainted = true;
   308                  fr_dcursor_append(&child_cursor, vp);
   309
   310                  if (fr_dict_attr_is_key_field(vp->da)) key_vp = vp;
   311
   312                  /*
   313                   *      Note that we're decoding fixed fields here.
   314                   *      So we skip the input based on the *known*
   315                   *      length, and not on the *decoded* length.
   316                   */
   317                  p += child_length;
   318                  child_num++;    /* go to the next child */
   319          }
   320
   321          /*
   322           *      Is there a substructure after this one?  If so, go
   323           *      decode it.
   324           */
   325          if (key_vp) {
   326                  ssize_t slen;
   327                  fr_dict_enum_value_t const *enumv;
   328                  child = NULL;
   329
   330                  FR_PROTO_HEX_DUMP(p, (end - p), "fr_struct_from_network - substruct");
   331
   332                  /*
   333                   *      Nothing more to decode, don't decode it.
   334                   */
   335                  if (p >= end) {
   336                          FR_PROTO_TRACE("Expected substruct, but there is none. We're done decoding this structure");
   337                          goto done;
   338                  }
   339
   340                  enumv = fr_dict_enum_by_value(key_vp->da, &key_vp->data);
   341                  if (enumv) child = enumv->child_struct[0];
   342
   343                  if (!child) {
   344                  unknown_child:
   345                          /*
   346                           *      Encode the unknown child as attribute
   347                           *      number 0.  This choice means we don't
   348                           *      have to look up, or keep track of, the
   349                           *      number of children of the key field.
   350                           */
   351                          child = fr_dict_unknown_afrom_fields(child_ctx, key_vp->da,
   352                                                               fr_dict_vendor_num_by_da(key_vp->da), 0);
   353                          if (!child) {
   354                                  FR_PROTO_TRACE("failed allocating unknown child?");
   355                                  goto unknown;
   356                          }
   357
   358                          vp = fr_raw_from_network(child_ctx, child, p, end - p);
   359                          if (!vp) {
   360                                  FR_PROTO_TRACE("Failed creating raw VP from malformed or unknown substruct");
   361                                  fr_dict_unknown_free(&child);
   362                                  return -(p - data);
   363                          }
   364
   365                          fr_dcursor_append(&child_cursor, vp);
   366                          p = end;
   367                  } else {
   368                          fr_assert(child->type == FR_TYPE_STRUCT);
   369
   370                          slen = fr_struct_from_network(child_ctx, &child_cursor, child, p, end - p, nested,
   371                                                        decode_ctx, decode_value, decode_tlv);
   372                          if (slen <= 0) {
   373                                  FR_PROTO_TRACE("substruct %s decoding failed", child->name);
   374                                  goto unknown_child;
   375                          }
   376                          p += slen;
   377                  }
   378
   379                  fr_dict_unknown_free(&child);
   380
   381                  /*
   382                   *      Else return whatever we decoded.  Note that if
   383                   *      the substruct ends in a TLV, we decode only as
   384                   *      many TLVs as the various "length" fields say.
   385                   */
   386                  data_len = p - data;
   387          }
   388
   389  done:
   390          if (!nested) {
   391                  fr_dcursor_head(&child_cursor);
   392                  fr_dcursor_tail(cursor);
   393                  fr_dcursor_merge(cursor, &child_cursor);        /* Wind to the end of the new pairs */
   394          } else {
   395                  fr_assert(struct_vp != NULL);
   396                  fr_dcursor_append(cursor, struct_vp);
   397          }
   398
   399          FR_PROTO_TRACE("used %zd bytes", data_len);
   400          return data_len;
   401  }
