   404  /** Put bits into an output dbuff
   405   *
   406   * @param dbuff         where the bytes go
   407   * @param p             where leftover bits go
   408   * @param start_bit     start bit in the dbuff where the data goes, 0..7
   409   * @param num_bits      number of bits to write to the output, 0..55
   410   * @param data          data to write, all in the lower "num_bits" of the uint64_t variable
   411   * @return
   412   *      >= 0    the next value to pass in for start_bit
   413   *      <  0    no space or invalid start_bit or num_bits parameter
   414   */
   415  static int put_bits_dbuff(fr_dbuff_t *dbuff, uint8_t *p, int start_bit, uint8_t num_bits, uint64_t data)
   416  {
   417          uint64_t        used_bits;
   418
   419          if (start_bit < 0 || start_bit > 7) return -1;
   420          if (num_bits < 1 || num_bits > 56) return -1;
